func htGv(gv *port.Cells, nt int32, no int32, nh int32, simfold int32, plaus int32, hlatin int32, hink int32, hinkwin int32, margin int32, pageocr int32) int32 {
	// A hidden group's columns (the others zero, the OCR plausibility `plaus`).
	for port.CellsLen(gv) < fuserules.AgCount() {
		port.CellsPush(gv, 0)
	}
	port.CellsSet(gv, fuserules.AgNt(), nt)
	port.CellsSet(gv, fuserules.AgNo(), no)
	port.CellsSet(gv, fuserules.AgNh(), nh)
	port.CellsSet(gv, fuserules.AgSimfold(), simfold)
	port.CellsSet(gv, fuserules.AgPlaus(), plaus)
	port.CellsSet(gv, fuserules.AgHlatin(), hlatin)
	port.CellsSet(gv, fuserules.AgHink(), hink)
	port.CellsSet(gv, fuserules.AgHinkwin(), hinkwin)
	port.CellsSet(gv, fuserules.AgMargin(), margin)
	port.CellsSet(gv, fuserules.AgPageocr(), pageocr)
	return 0
}

func htRuleSplit(simfold int32) int32 {
	// a group of one hidden word and two OCR words
	var gv *port.Cells = port.NewCells()
	htGv(gv, 0, 2, 1, simfold, 1000, 1, -1, -1, -1, 0)
	port.CellsSet(gv, fuserules.AgHsplit(), 1)
	return fuserules.FrNumber(fuserules.FrDecide(gv))
}

