func TestEveryHiddenRuleDecidesWhatItsNumberSays(emonT *testing.T) {
	// args: nt no nh simfold plaus hlatin hink hinkwin margin pageocr
	port.AssertEq(emonT, htRule(0, 0, 2, -1, -1, 1, -1, -1, -1, 0), 301, "a hidden layer and no OCR on the page")
	port.AssertEq(emonT, htRule(0, 1, 2, 950, 1000, 1, -1, -1, -1, 0), 310, "hidden and OCR agree")
	port.AssertEq(emonT, htRule(0, 1, 2, 900, 1000, 1, -1, -1, -1, 0), 310, "exactly `agree-sim`")
	port.AssertEq(emonT, htRuleSplit(950), 311, "they agree on the letters but OCR split the hidden word: OCR's segmentation")
	port.AssertEq(emonT, htRuleSplit(100), 322, "they disagree: OCR as ever")
	port.AssertEq(emonT, htRule(0, 1, 2, 899, 1000, 0, -1, -1, -1, 0), 315, "they disagree, in a script the engine does not read")
	port.AssertEq(emonT, htRule(0, 1, 2, 100, 500, 1, -1, -1, -1, 0), 316, "they disagree and the OCR is implausible")
	port.AssertEq(emonT, htRule(0, 1, 2, 100, 1000, 1, -1, -1, 100, 0), 322, "they disagree: OCR (the hidden ink is not known)")
	port.AssertEq(emonT, htRule(0, 1, 2, 100, 1000, 1, 300, 1, 100, 0), 321, "a close call (margin 100) and better hidden ink: the hidden word")
	port.AssertEq(emonT, htRule(0, 1, 2, 100, 1000, 1, 300, 0, 100, 0), 322, "a close call but worse hidden ink: OCR")
	port.AssertEq(emonT, htRule(0, 1, 2, 100, 1000, 1, 300, 1, 600, 0), 322, "a margin of exactly `hid-margin` is not a close call")
	port.AssertEq(emonT, htRuleSame(-1, 350), 323, "one segmentation, a close call, no ink measured: the hidden word")
	port.AssertEq(emonT, htRuleSame(1, 350), 321, "(with better ink it is 321's)")
	port.AssertEq(emonT, htRuleSame(0, 350), 322, "(with worse ink it is OCR's)")
	port.AssertEq(emonT, htRuleSame(-1, 900), 322, "(a confident OCR word stays)")
	port.AssertEq(emonT, htRule(0, 1, 2, 100, 1000, 1, 300, 1, -1, 0), 322, "no margin: not a close call")
	port.AssertEq(emonT, htRule(0, 0, 2, -1, -1, 1, 100, -1, -1, 4), 330, "no OCR counterpart on a page OCR read, ink under the word: kept")
	port.AssertEq(emonT, htRule(0, 0, 2, -1, -1, 1, 30, -1, -1, 4), 330, "exactly `hid-ink`")
	port.AssertEq(emonT, htRule(0, 0, 2, -1, -1, 1, 29, -1, -1, 4), 331, "no ink: invisible")
	port.AssertEq(emonT, htRule(0, 0, 2, -1, -1, 1, 0, -1, -1, 4), 331, "no ink at all")
	port.AssertEq(emonT, htRule(0, 0, 2, -1, -1, 1, -1, -1, -1, 4), 332, "ink not measured: kept, never dropped on a guess")
	// a visible text-layer word is block 100's, whatever hidden words stand beside it
	var gv *port.Cells = port.NewCells()
	htGv(gv, 1, 1, 0, 950, 1000, 1, -1, -1, -1, 0)
	port.CellsSet(gv, fuserules.AgFont(), 1000)
	port.AssertEq(emonT, fuserules.FrNumber(fuserules.FrDecide(gv)), 110, "a visible word and OCR agree: the contract's row, not 310")
}

func TestTheHiddenRowsSayWhatTheySet(emonT *testing.T) {
	var gv *port.Cells = port.NewCells()
	htGv(gv, 0, 0, 2, -1, -1, 1, -1, -1, -1, 0)
	port.AssertEq(emonT, fuserules.FrWinner(fuserules.FrDecide(gv)), fuserules.FwText(), "301 is the text layer's")
	port.AssertEq(emonT, fuserules.FrConf(fuserules.FrDecide(gv)), 600, "at confidence 600")
	htGv(gv, 0, 1, 2, 950, 1000, 1, -1, -1, -1, 0)
	port.AssertEq(emonT, fuserules.FrWinner(fuserules.FrDecide(gv)), fuserules.FwText(), "310 is the hidden text's")
	port.AssertEq(emonT, fuserules.FrConf(fuserules.FrDecide(gv)), 950, "confidence up")
	port.AssertEq(emonT, fuserules.FrFlags(fuserules.FrDecide(gv)), 0, "unflagged")
	htGv(gv, 0, 1, 2, 100, 1000, 1, -1, -1, -1, 0)
	port.AssertEq(emonT, fuserules.FrWinner(fuserules.FrDecide(gv)), fuserules.FwOcr(), "322 is OCR's")
	port.AssertEq(emonT, fuserules.FrConf(fuserules.FrDecide(gv)), -1, "with the OCR's own score for confidence")
	htGv(gv, 0, 1, 2, 100, 1000, 1, 300, 1, 100, 0)
	port.AssertEq(emonT, fuserules.FrFlags(fuserules.FrDecide(gv)), 1, "321 is low-conf")
	htGv(gv, 0, 0, 2, -1, -1, 1, 0, -1, -1, 4)
	port.AssertEq(emonT, fuserules.FrWinner(fuserules.FrDecide(gv)), fuserules.FwNone(), "331 holds the word")
	port.AssertEq(emonT, fuserules.FrReason(fuserules.FrDecide(gv)), model.DrInvisible(), "as invisible")
}

