func htGroup(cg *port.Cells, refs *port.Cells, hword int32, nh int32, oword int32, no int32, simfold int32) int32 {
	// A group of page 1 over `nh` hidden words from `hword` and `no` OCR words from `oword` (no visible word); answers it.
	var g int32 = player.CgNew(cg, 1, 0, 0, 3000, 1000, 0)
	var first int32 = -1
	var i int32 = 0
	if nh > 0 {
		first = evidence.RfAdd(refs, evidence.EaWords(), hword)
		i = 1
		for i < nh {
			evidence.RfAdd(refs, evidence.EaWords(), hword+i)
			i += 1
		}
		player.CgSet(cg, g, player.CgfHfirst(), first)
		player.CgSet(cg, g, player.CgfHcount(), nh)
	}
	if no > 0 {
		first = evidence.RfAdd(refs, evidence.EaOwords(), oword)
		i = 1
		for i < no {
			evidence.RfAdd(refs, evidence.EaOwords(), oword+i)
			i += 1
		}
		player.CgSet(cg, g, player.CgfOfirst(), first)
		player.CgSet(cg, g, player.CgfOcount(), no)
	}
	player.CgSet(cg, g, player.CgfSimfold(), simfold)
	return g
}

