func TestHxFillMeasuresTheHiddenColumns(emonT *testing.T) {
	var fw *port.Cells = port.NewCells()
	var feats *port.Cells = port.NewCells()
	var et *port.Cells = port.NewCells()
	var ow *port.Cells = port.NewCells()
	var cg *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var gv *port.Cells = port.NewCells()
	var h0 int32 = htHword(fw, feats, et, 0, 0, 104, 101, 200)
	var h1 int32 = htHword(fw, feats, et, 1000, 0, 109, 111, 400)
	var h2 int32 = htHword(fw, feats, et, 2000, 0, 120, 121, -1)
	var o0 int32 = htOword(ow, feats, et, 0, 104, 101, 120, 100)
	var o1 int32 = htOword(ow, feats, et, 1000, 109, 111, 80, 100)
	var g0 int32 = htGroup(cg, refs, h0, 2, o0, 2, 950)
	var g1 int32 = htGroup(cg, refs, h2, 1, 0, 0, -1)
	for port.CellsLen(gv) < fuserules.AgCount() {
		port.CellsPush(gv, 0)
	}
	hidden.HxFill(g0, cg, refs, fw, et, feats, ow, gv)
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgHlatin()), 1, "Latin hidden words are read by the engine")
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgHink()), 300, "the mean ink of the two hidden words")
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgHinkwin()), 1, "300 against 100: the hidden ink agrees better")
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgMargin()), 80, "the lowest margin of the OCR words")
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgPageocr()), 0, "a group with OCR has no page count")
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgHsplit()), 0, "two words and two words: no split")
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgHsame()), 1, "and one segmentation")
	hidden.HxFill(g1, cg, refs, fw, et, feats, ow, gv)
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgHink()), -1, "ink not measured")
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgHinkwin()), -1, "so the comparison is not made")
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgMargin()), -1, "no OCR word: no margin")
	port.AssertEq(emonT, port.CellsAt(gv, fuserules.AgPageocr()), 2, "the page's OCR words, for a group with none")
}

