	var nfl *port.Cells = port.NewCells()
	var fv *port.Cells = port.NewCells()
	var fx *port.Cells = port.NewCells()
	var afa *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var tmp *port.Cells = port.NewCells()
	var tt *port.Cells = port.NewCells()
	var h0 int32 = htHword(fw, feats, et, 0, 0, 104, 101, -1)
	var h1 int32 = htHword(fw, feats, et, 1000, 0, 109, 111, 0)
	var h2 int32 = htHword(fw, feats, et, 2000, 0, 120, 121, 500)
	var h3 int32 = htHword(fw, feats, et, 3000, 0, 98, 98, -1)
	var o0 int32 = htOword(ow, feats, et, 0, 104, 101, 500, -1)
	htLine(fl, 4)
	htGroup(cg, refs, h0, 1, o0, 1, 1000)
	htGroup(cg, refs, h1, 1, 0, 0, -1)
	htGroup(cg, refs, h2, 1, 0, 0, -1)
